async (page) => {
  const context = await page.context().browser().newContext();
  const p = await context.newPage();
  const observations = [];
  const consoleErrors = [];
  const failedResources = [];
  let phase = 'start';
  p.on('console', m => { if (m.type() === 'error') consoleErrors.push({phase, text: m.text().replace(/https?:\/\/[^\s]+/g, raw => { try { const u = new URL(raw); return u.origin + u.pathname; } catch { return '[URL omitted]'; } }).slice(0, 500)}); });
  p.on('response', r => { if (r.status() >= 400) { const u = new URL(r.url()); failedResources.push({phase, status:r.status(), resource:u.origin+u.pathname}); } });
  const sites = [
    ['resident','https://ca-resident-demo.happyriver-ace49996.uksouth.azurecontainerapps.io'],
    ['employee','https://ca-cutover-test-demo-api.happyriver-ace49996.uksouth.azurecontainerapps.io']
  ];
  try {
    for (const [site, host] of sites) {
      phase = site+'-health';
      const health = await p.request.get(host+'/healthz', {timeout:180000});
      if (health.status() !== 200) throw new Error(site+' browser health '+health.status());
      for (const [width,height] of [[1365,900],[390,844]]) {
        phase = site+'-'+width;
        await p.setViewportSize({width,height});
        const response = await p.goto(host+'/', {waitUntil:'networkidle',timeout:180000});
        const dom = await p.evaluate(() => ({
          overflow: document.documentElement.scrollWidth > innerWidth,
          passwords:document.querySelectorAll('input[type=password]').length,
          sharedWidgetScripts:document.querySelectorAll('script[src="/chat-widget.js"]').length,
          launchers:document.querySelectorAll('.zf-chat-launcher').length,
          dialogs:document.querySelectorAll('[role=dialog]').length,
          signInLinks:Array.from(document.querySelectorAll('a')).filter(a => /sign in/i.test(a.textContent)).length
        }));
        observations.push({site,width,height,status:response.status(),health:health.status(),...dom});
      }
    }
    phase = 'employee-anonymous-app';
    await p.goto(sites[1][1]+'/app', {waitUntil:'domcontentloaded',timeout:180000});
    const final = new URL(p.url());
    return {freshAnonymousContext:true,observations,employeeApp:{origin:final.origin,path:final.pathname,authenticationAttempted:false},consoleErrors,failedResources,credentialsEntered:false,modelInvocations:0};
  } finally { await context.close(); }
}

async (page) => {
 const context = await page.context().browser().newContext();
 const p = await context.newPage();
 const results=[];
 try {
  const host='https://ca-resident-demo.happyriver-ace49996.uksouth.azurecontainerapps.io';
