   const visible=count===1 && await launcher.isVisible();
   if(visible) await launcher.click();
   results.push({site:'resident',width,height,status:response.status(),correctSelector:'.chat-widget-launcher',launcherCount:count,launcherVisible:visible,expanded:count===1?await launcher.getAttribute('aria-expanded'):null,visibleDialogs:await p.locator('[role=dialog]:visible').count(),overflow:await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),credentialFieldsFilled:0,formsSubmitted:0});
  }
  return {correction:'Prior .zf-chat-launcher selector did not match repository widget class; prior zero was not widget absence',results,authenticated:false,modelInvocations:0};
 } finally {await context.close();}
